@Bean
public Job sequentialFlowJob() {
    return jobBuilderFactory.get("sequentialFlowJob")
            .start(firstStep())    // First step
            .next(secondStep())    // Second step
            .next(thirdStep())     // Third step
            .build();
}

@Bean
public Job conditionalFlowJob() {
    return jobBuilderFactory.get("conditionalFlowJob")
            .incrementer(new RunIdIncrementer())
            .start(flowFirstStep())
                .on("FAILED").to(flowThirdStep())   // If first step fails, go to third step
            .from(flowFirstStep())
                .on("*").to(flowSecondStep())      // Otherwise, go to second step
            .end()
            .build();
}

public class MyFlowDecider implements JobExecutionDecider {
    @Override
    public FlowExecutionStatus decide(JobExecution jobExecution, StepExecution stepExecution) {
        String result = LocalDateTime.now().getHour() < 12 ? "FN" : "AN";
        return new FlowExecutionStatus(result);
    }
}

@Bean
public Job deciderJob() {
    return jobBuilderFactory.get("deciderJob")
            .start(deciderFirstStep())
            .next(decider())                     // Invoke the decider
            .from(decider())
                .on("FN").to(deciderSecondStep()) // Morning path
            .from(decider())
                .on("*").to(deciderThirdStep())  // All other paths
            .end()
            .build();
}

@Bean
public JobExecutionDecider decider() {
    return new MyFlowDecider();
}

